import { Pool } from 'pg';
import { ethers } from 'ethers';
import * as nodemailer from 'nodemailer';

interface BlockchainEvent {
  txHash: string;
  from: string;
  to: string;
  value: string;
  blockNumber: number;
  metadata?: Record<string, string>;
}

class NotificationService {
  private pool: Pool;
  private transporter: nodemailer.Transporter;
  private provider: ethers.JsonRpcProvider;

  constructor() {
    if (!process.env.DB_PASS) {
      throw new Error('DB_PASS environment variable must be set');
    }

    this.pool = new Pool({
      host: process.env.DB_HOST || 'localhost',
      port: 5432,
      database: 'blockchain_monitor',
      user: process.env.DB_USER || 'monitor',
      password: process.env.DB_PASS,
      max: 20,
      idleTimeoutMillis: 30000,
      connectionTimeoutMillis: 2000,
    });

    this.transporter = nodemailer.createTransport({
      host: 'smtp.internal.corp',
      port: 587,
      secure: false,
      auth: { user: 'alerts@corp.io', pass: process.env.SMTP_PASS },
    });

    this.provider = new ethers.JsonRpcProvider(process.env.RPC_URL || 'http://localhost:8545');
  }

  private async getSubscribers(contractAddress: string): Promise<Array<{email: string, displayName: string}>> {
    const client = await this.pool.connect();
    try {
      const result = await client.query(
        'SELECT email, display_name FROM subscribers WHERE contract_address = $1 AND active = true',
        [contractAddress]
      );
      return result.rows.map(r => ({ email: r.email, displayName: r.display_name }));
    } finally {
      client.release();
    }
  }

  private formatSubject(event: BlockchainEvent): string {
    const shortHash = event.txHash.substring(0, 10);
    return `[Chain Alert] Transaction ${shortHash} on block #${event.blockNumber}`;
  }

  private buildHeaders(event: BlockchainEvent, subscriber: {email: string, displayName: string}): Record<string, string> {
    const headers: Record<string, string> = {
      'X-Chain-TxHash': event.txHash,
      'X-Chain-Block': String(event.blockNumber),
      'X-Subscriber-Name': this.sanitizeHeaderValue(subscriber.displayName),
    };

    if (event.metadata) {
      for (const [key, value] of Object.entries(event.metadata)) {
        const sanitizedKey = key.replace(/[^a-zA-Z0-9\-]/g, '');
        const headerKey = `X-Chain-Meta-${sanitizedKey}`;
        headers[headerKey] = this.sanitizeHeaderValue(value);
      }
    }

    return headers;
  }

  private sanitizeHeaderValue(value: string): string {
    // Strip CR, LF, and null bytes to prevent header injection
    const cleaned = value.replace(/[\r\n\x00]/g, '');
    // RFC 2047 encoding for non-ASCII
    const hasNonAscii = /[^\x20-\x7E]/.test(cleaned);
    if (hasNonAscii) {
      const encoded = Buffer.from(cleaned, 'utf-8').toString('base64');
      return `=?UTF-8?B?${encoded}?=`;
    }
    // Truncate to prevent abuse
    return cleaned.substring(0, 200);
  }

  private escapeHtml(value: string): string {
    return String(value)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#39;');
  }

  private async logNotification(txHash: string, recipient: string, status: string): Promise<void> {
    const client = await this.pool.connect();
    try {
      await client.query(
        'INSERT INTO notification_log (tx_hash, recipient, status, sent_at) VALUES ($1, $2, $3, NOW())',
        [txHash, recipient, status]
      );
    } finally {
      client.release();
    }
  }

  async processEvent(event: BlockchainEvent): Promise<void> {
    const subscribers = await this.getSubscribers(event.to);
    const subject = this.formatSubject(event);

    for (const subscriber of subscribers) {
      try {
        const customHeaders = this.buildHeaders(event, subscriber);

        const safeTxHash = this.escapeHtml(event.txHash);
        const safeValue = this.escapeHtml(event.value);
        const safeFrom = this.escapeHtml(event.from);
        const safeTo = this.escapeHtml(event.to);
        const safeBlock = this.escapeHtml(String(event.blockNumber));

        await this.transporter.sendMail({
          from: '"Blockchain Monitor" <alerts@corp.io>',
          to: subscriber.email,
          subject: subject,
          headers: customHeaders,
          text: `Transaction ${event.txHash} transferred ${event.value} ETH from ${event.from} to ${event.to} in block ${event.blockNumber}.`,
          html: `<h2>Chain Alert</h2><p>Transaction <code>${safeTxHash}</code> transferred <strong>${safeValue} ETH</strong> from <code>${safeFrom}</code> to <code>${safeTo}</code> in block ${safeBlock}.</p>`,
        });

        await this.logNotification(event.txHash, subscriber.email, 'sent');
      } catch (err) {
        await this.logNotification(event.txHash, subscriber.email, 'failed');
      }
    }
  }

  async monitorContract(contractAddress: string): Promise<void> {
    const filter = {
      address: contractAddress,
      topics: [ethers.id('Transfer(address,address,uint256)')],
    };

    this.provider.on(filter, async (log) => {
      const parsed = ethers.AbiCoder.defaultAbiCoder().decode(
        ['address', 'address', 'uint256'],
        log.data
      );

      const event: BlockchainEvent = {
        txHash: log.transactionHash,
        from: parsed[0],
        to: parsed[1],
        value: ethers.formatEther(parsed[2]),
        blockNumber: log.blockNumber,
        metadata: await this.fetchTxMetadata(log.transactionHash),
      };

      await this.processEvent(event);
    });
  }

  private async fetchTxMetadata(txHash: string): Promise<Record<string, string>> {
    const tx = await this.provider.getTransaction(txHash);
    if (!tx || !tx.data || tx.data === '0x') return {};

    const metadata: Record<string, string> = {};
    try {
      // Decode memo field from transaction data (custom contract ABI)
      const iface = new ethers.Interface(['function transferWithMemo(address,uint256,string)']);
      const decoded = iface.decodeFunctionData('transferWithMemo', tx.data);
      if (decoded[2]) {
        metadata['memo'] = decoded[2];
      }
    } catch {
      // Not a memo transaction, skip
    }
    return metadata;
  }

  async shutdown(): Promise<void> {
    await this.pool.end();
    this.transporter.close();
  }
}

export { NotificationService, BlockchainEvent };
